import {detailSections,enhanceProductDetails} from './perfume-details.js';
import {referenceShell,mountReferences,referenceStoreGuide} from './reference-catalogs.js';
let detailsCleanup=()=>{};
import {products,settings,curated,articles} from './catalog.js';
import {byId,escapeHTML as esc,cleanCart,summarize,addItem,filterProducts,recommend,bundleTotal} from './shop-core.js';
const $=(s,root=document)=>root.querySelector(s);
const money=cents=>new Intl.NumberFormat(settings.locale,{style:'currency',currency:settings.currency,maximumFractionDigits:0}).format(cents/100);
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const write=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{toast('Browser storage is unavailable. Your choices are saved for this visit.')}};
const validIds=items=>Array.isArray(items)?[...new Set(items.map(Number))].filter(id=>byId(id)):[];
let cart=cleanCart(read('maison-bag-v2',read('maison-cart',[]))),saved=validIds(read('maison-favorites',[])),compared=[],recent=validIds(read('maison-recent',[]));
let note=read('maison-order-note','');if(typeof note!=='string')note='';
let toastTimer,artId=0,bundleIds=[],bundleCount=3,bundleGender='All',bundleSize=50,quizStep=0,quizAnswers={},productSize=50,productQty=1;
const quizQuestions=[{key:'family',title:'What draws you in?',intro:'Start with a note you already love.',options:[['Fresh','Citrus & fresh air','Bright, green, and light.'],['Floral','A garden in bloom','Petals, soft florals, and a little romance.'],['Woody','Woods & quiet moments','Earthy, dry, and beautifully grounded.'],['Gourmand','Something sweet','Vanilla, soft fruit, and warmth.'],['Amber','Golden-hour warmth','Amber, spice, and a little depth.']]},{key:'mood',title:'How do you want to feel?',intro:'There is no wrong answer.',options:[['Bright','Bright & effortless','An easy lift to your everyday.'],['Grounded','Calm & confident','Something quietly distinctive.'],['Romantic','Soft & expressive','A little warmth, a little mystery.'],['Warm','Comfortable & wrapped up','A familiar feeling to carry with you.']]},{key:'occasion',title:'When will you wear it?',intro:'Build your match around your life.',options:[['Everyday','Every day','Your signature, on repeat.'],['Work','Work & focus','An understated everyday companion.'],['Evening','When the sun goes down','An evening mood.'],['Occasion','For a special moment','Something memorable.']]},{key:'gender',title:'What would you like to explore?',intro:'Fragrance has no rules. Choose what interests you.',options:[['All','Everything','Keep the possibilities open.'],['Women','The collection for her','Explore our feminine edit.'],['Men','The collection for him','Explore our masculine edit.'],['Unisex','The unisex collection','Made for everyone.']]}];
const faq=[['Can I place an order today?','The storefront is open to explore. Online ordering begins once our confirmed products, payment provider, and fulfillment are connected. Your bag is saved only in this browser.'],['How do I choose a fragrance?','Start with the scent quiz, browse by fragrance family, or compare the notes on product pages. Gender categories are simply browsing shortcuts; wear what you enjoy.'],['What do the notes mean?','Notes describe a fragrance’s impression, not its full ingredient list. Top notes are the opening, heart notes shape the middle, and base notes describe the finish.'],['Are the products and prices final?','This is a proposed launch collection. Names, fragrance profiles, sizes, and prices are indicative and will be confirmed before orders open.'],['How much fragrance oil is in each perfume?','The final formulas and oil concentrations have not been confirmed. The fragrance guide explains concentration types without promising a specific percentage for MAISON.'],['Where do you ship?','Available countries, shipping charges, delivery estimates, and any free-shipping offers will be published before checkout opens.'],['What is your return policy?','Return eligibility, time limits, and instructions will be available before orders open. There is no active money-back offer during the preview.'],['How do bundles work?','Choose a curated trio, or build a set of three or five in any of the preview sizes. The builder adds exactly those fragrances to your bag at their displayed prices. No unconfirmed discount or gift is included.']];
function bottle(p,cls=''){const id='b'+(++artId);return `<svg class="bottle-art ${cls}" viewBox="0 0 250 310" aria-hidden="true"><defs><linearGradient id="${id}c"><stop stop-color="#aaa9a3"/><stop offset=".2" stop-color="#e8e7e2"/><stop offset=".48" stop-color="#aaa9a3"/><stop offset=".73" stop-color="#f5f4ef"/><stop offset="1" stop-color="#a4a39c"/></linearGradient><linearGradient id="${id}g"><stop stop-color="#ffffff" stop-opacity=".8"/><stop offset=".15" stop-color="${p.color}" stop-opacity=".4"/><stop offset=".75" stop-color="${p.color}" stop-opacity=".8"/><stop offset="1" stop-color="#fff" stop-opacity=".6"/></linearGradient><filter id="${id}s" x="-50%" y="-50%" width="220%" height="220%"><feGaussianBlur stdDeviation="5"/></filter></defs><ellipse cx="141" cy="282" rx="78" ry="8" fill="#665338" opacity=".18" filter="url(#${id}s)"/><rect x="98" y="23" width="56" height="64" rx="3" fill="url(#${id}c)"/><rect x="104" y="82" width="44" height="8" fill="#9e9b87"/><rect x="48" y="90" width="156" height="185" rx="13" fill="url(#${id}g)" stroke="#ffffff" stroke-width="2"/><rect x="55" y="97" width="142" height="169" rx="9" fill="none" stroke="#dacbae" stroke-opacity=".65" stroke-width="3"/><path d="M61 104v147M187 106v144" stroke="#fff" opacity=".6" stroke-width="4"/><rect x="66" y="126" width="120" height="108" fill="#f7f3e9"/><rect x="72" y="132" width="108" height="96" fill="none" stroke="#b8aa92" stroke-width=".4"/><text x="126" y="162" text-anchor="middle" font-family="Georgia,serif" font-size="21" letter-spacing="1">MAISON</text><text x="126" y="185" text-anchor="middle" font-family="Arial,sans-serif" font-size="7" letter-spacing=".7">${esc(p.name.toUpperCase())}</text><text x="126" y="208" text-anchor="middle" font-family="Arial,sans-serif" font-size="5" letter-spacing="1.5">THE EVERYDAY COLLECTION</text><path d="M57 260q67 12 138 0" fill="none" stroke="#fff" opacity=".8" stroke-width="3"/></svg>`}
function heading(kicker,title,link='',href='#/shop'){return `<div class="section-heading"><div><p class="eyebrow">${kicker}</p><h2>${title}</h2></div>${link?`<a class="text-link" href="${href}">${link} ↗</a>`:''}</div>`}
function card(p,{bundle=false,mini=false}={}){const heart=saved.includes(p.id),compare=compared.includes(p.id),selected=bundleIds.includes(p.id);return `<article class="product-card ${mini?'mini-card':''}"><div class="product-image tone-${p.family.toLowerCase()}"><span class="product-tag">${p.tag}</span><button class="heart ${heart?'selected':''}" data-save="${p.id}" aria-label="${heart?'Unsave':'Save'} ${p.name}" aria-pressed="${heart}">${heart?'♥':'♡'}</button><a href="#/product/${p.slug}" aria-label="Explore ${p.name}">${bottle(p)}</a><button class="quick-view" data-quick="${p.id}">Quick view <span>+</span></button></div><div class="product-meta"><span>${p.family} · ${p.category}</span><span>EAU DE PARFUM</span></div><div class="product-title"><a href="#/product/${p.slug}">${p.name}</a><span>${money(bundle?p.variants.find(v=>v.size===bundleSize).price:p.price)}</span></div><p class="product-notes">${p.top[0]} · ${p.heart[0]} · ${p.base[0]}</p>${bundle?`<button class="button ${selected?'selected':'secondary'} card-button" data-bundle-item="${p.id}" aria-pressed="${selected}">${selected?'Selected ✓':'Add to my set +'}</button>`:`<div class="card-actions"><button class="button secondary card-button" data-add="${p.id}">Add to bag <span>+</span></button><button class="compare-button ${compare?'selected':''}" data-compare="${p.id}" aria-label="${compare?'Remove':'Add'} ${p.name} ${compare?'from':'to'} comparison" aria-pressed="${compare}">⇄</button></div>`}</article>`}
function cards(items,options){return items.map(p=>card(p,options)).join('')}
function curatedCards(){return curated.map((set,i)=>`<article class="curated-card ${set.tone}"><a href="#/bundle?set=${i}" class="curated-art" aria-label="Explore ${set.name}">${set.ids.map(id=>bottle(byId(id))).join('')}</a><div><p class="eyebrow">THE CURATED TRIO</p><h3>${set.name}</h3><p>${set.subtitle}</p><button class="text-link" data-curated="${i}">Make it my set ↗</button></div></article>`).join('')}
function reviewsBlock(){return `<section class="reviews-section section" id="reviews">${heading('THE COMMUNITY','Your experience matters.','Review information','#/reviews')}<div class="tab-list" aria-label="Review topics">${['All','Longevity','Scent','Quality','Experience'].map((t,i)=>`<button data-review-topic="${t}" aria-pressed="${i===0}" class="pill ${i===0?'active':''}">${t}</button>`).join('')}</div><div class="review-empty" id="reviewResults" role="status"><span class="empty-icon">“</span><h3>A new story starts here.</h3><p>Customer reviews will appear after launch. No reviews have been collected yet.</p></div></section>`}
function faqs(){return `<div class="faq-list">${faq.map(([q,a])=>`<details><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('')}</div>`}
function newsletter(){return `<section class="newsletter"><div><p class="eyebrow">GOOD THINGS, IN THE AIR</p><h2>A little more MAISON.</h2><p>Future scent stories, new collections, and the first word on our launch.</p></div><div><p class="newsletter-note">Our mailing list is opening soon. For now, bookmark the collection or save your favorites.</p><a class="button light" href="#/saved">MY SAVED FRAGRANCES ↗</a></div></section>`}
function home(){return `<section class="home-hero"><img src="assets/maison-campaign.png" alt="Original MAISON fragrance campaign: amber-filled glass bottles on sunlit stone with bergamot and an olive branch" width="1536" height="1024" fetchpriority="high"><div class="hero-copy"><p class="eyebrow">THE EVERYDAY COLLECTION / 01</p><h1>Make it<br>your signature.</h1><p>For your everyday.<br>And every side of you.</p><a class="button" href="#/shop">FIND YOUR FRAGRANCE <span>↗</span></a><a class="hero-quiz" href="#/quiz">Need a little inspiration? Take the scent quiz →</a></div><span class="hero-caption">A NEW CHAPTER IN EVERYDAY LUXURY.</span></section><div class="benefit-ribbon"><span>FIND YOUR SIGNATURE</span><i>✳</i><span>BUILD YOUR OWN SET</span><i>✳</i><span>EXPLORE THE NOTES</span><i>✳</i><span>MAKE IT A RITUAL</span></div>
<section class="section signature-section">${heading('MEET YOUR NEXT FAVORITE','The signature edit.','Explore the collection')}<div class="gender-tabs tab-list" aria-label="Browse signature fragrances">${[['All','All fragrances'],['Women','For her'],['Men','For him'],['Unisex','For everyone']].map(([value,text],i)=>`<button class="pill ${i===0?'active':''}" data-home-gender="${value}" aria-pressed="${i===0}">${text}</button>`).join('')}<div class="rail-controls"><button data-rail="signatureRail" data-direction="-1" aria-label="Previous fragrances">←</button><button data-rail="signatureRail" data-direction="1" aria-label="Next fragrances">→</button></div></div><div class="product-rail" id="signatureRail">${cards(products.slice(0,6))}</div><p class="fine-print">Preview collection. Displayed sizes, fragrance profiles, and pricing are indicative.</p></section>
<section class="category-section section"><p class="eyebrow">FOLLOW YOUR SENSES</p><h2>There's a little you in every note.</h2><div class="category-grid">${[['For him','gender=Men',2],['For everyone','gender=Unisex',1],['For her','gender=Women',3],['Something sweet','family=Gourmand',5],['A fresh start','family=Fresh',4]].map(([title,query,id])=>`<a href="#/shop?${query}"><div class="category-circle tone-${byId(id).family.toLowerCase()}">${bottle(byId(id))}</div><span>${title} ↗</span></a>`).join('')}</div></section>
<section class="bundle-intro"><div><p class="eyebrow">ONE SCENT IS JUST THE BEGINNING</p><h2>Your mood changes.<br>Your fragrance can, too.</h2><p>A bright morning. A quiet afternoon. An evening that belongs to you. Build a set that feels like every side of you.</p><a class="button" href="#/bundle">BUILD YOUR OWN BUNDLE ↗</a></div><div class="bundle-still">${[4,1,3].map(id=>bottle(byId(id))).join('')}<span>THE SIGNATURE TRIO</span></div></section>
<section class="section">${heading('A LITTLE DIRECTION','A collection, already considered.','All bundles','#/bundle')}<div class="curated-grid">${curatedCards()}</div></section>
<section class="why-section section"><div><p class="eyebrow">THE MAISON POINT OF VIEW</p><h2>Less about the label.<br>More about the feeling.</h2><a class="text-link" href="#/story">Get to know us ↗</a></div><div class="values-grid"><article><span>01 / PERSONAL</span><h3>Follow your own taste.</h3><p>Explore by mood and notes. Find the profile that speaks to you.</p></article><article><span>02 / CONSIDERED</span><h3>Room for a second favorite.</h3><p>Build a fragrance wardrobe around the moments in your day.</p></article><article><span>03 / CURIOUS</span><h3>Know your notes.</h3><p>Compare the opening, heart, and base before choosing your next scent.</p></article><article><span>04 / EVERYDAY</span><h3>A ritual worth keeping.</h3><p>A small moment for yourself, whether you're going out or staying in.</p></article></div></section>
<section class="guide-teaser section"><div><p class="eyebrow">SCENT SCHOOL, WITHOUT THE COMPLICATION</p><h2>It's what is inside<br>that makes a fragrance.</h2><p>Discover fragrance families, concentration types, and how a composition unfolds.</p><a class="text-link" href="#/guide">Explore the fragrance guide ↗</a></div><div class="note-stack"><div><span>01</span><b>THE OPENING</b><p>Bright. Immediate. Your first impression.</p></div><div><span>02</span><b>THE HEART</b><p>The character at the center of the scent.</p></div><div><span>03</span><b>THE FINISH</b><p>Depth, texture, and a lasting impression.</p></div></div></section>
${reviewsBlock()}<section class="section new-section">${heading('A FRESH CHAPTER','New notes. New possibilities.','Meet the new collection','#/shop?edit=new')}<div class="product-rail">${cards(products.slice(6))}</div></section><section class="quiz-banner"><span class="eyebrow">YOUR NEXT FAVORITE IS OUT THERE</span><h2>A few little clues.<br>A scent that feels like you.</h2><a class="button" href="#/quiz">FIND MY SCENT ↗</a><p>Four questions. A world of possibilities.</p></section><section class="section inspiration-entry"><div><p class="eyebrow">THE STORES THAT INSPIRED US</p><h2>More scents.<br>Every listed detail.</h2><p>Explore the attributed ALT and Scentora catalogs: product galleries, fragrance references, note diagrams, ingredients where published, bottle options, and source pricing.</p><a class="button" href="#/references">EXPLORE THE INSPIRATION LIBRARY &#8599;</a></div><div><span>ALT.</span><span>SCENTORA</span><p>Independent retailers. Their own products and policies.<br>Reference snapshot: 23 October 2026.</p><a class="text-link" href="#/reference-stores">About the reference stores &#8599;</a></div></section><section class="section journal-home">${heading('THE SCENT JOURNAL','A little inspiration, bottled.','Read the journal','#/journal')}<div class="journal-grid">${journalCards()}</div></section><section class="section faq-section"><div><p class="eyebrow">GOOD TO KNOW</p><h2>A few things<br>you might ask.</h2><a class="text-link" href="#/support">Visit the help center ↗</a></div>${faqs()}</section>${newsletter()}`}
function journalCards(){return articles.map((a,i)=>`<a href="#/journal/${a.slug}" class="journal-card"><div class="journal-art journal-art-${i}"><span>${['THE SCENT<br>SPECTRUM','TOP.<br>HEART.<br>BASE.','A SCENT<br>FOR EVERY<br>SIDE OF YOU.'][i]}</span></div><p class="eyebrow">${a.category} · ${a.minutes} MIN READ</p><h3>${a.title}</h3><span class="text-link">Read the story ↗</span></a>`).join('')}
function shop(params=new URLSearchParams()){const gender=params.get('gender')||'All',family=params.get('family')||'All',edit=params.get('edit')||'all';return `<section class="page-top"><p class="eyebrow">THE EVERYDAY COLLECTION</p><h1>${edit==='new'?'New possibilities.':edit==='signature'?'The signature edit.':'Find your kind of fragrance.'}</h1><p>Follow your notes. Change your mood. Make it yours.</p></section><section class="section shop-section"><div class="shop-toolbar"><div class="tab-list">${['All','Women','Men','Unisex'].map(g=>`<button class="pill ${g===gender?'active':''}" data-shop-gender="${g}" aria-pressed="${g===gender}">${g==='All'?'All fragrances':g==='Women'?'For her':g==='Men'?'For him':'For everyone'}</button>`).join('')}</div><label>Sort by <select id="shopSort"><option value="featured">Featured</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option><option value="name">Name: A–Z</option></select></label></div><div class="shop-layout"><aside class="filter-sidebar"><h2>Refine your search</h2><label>Search the collection<input id="shopSearch" type="search" value="${esc(params.get('q')||'')}" placeholder="Name or note…"></label><label>Fragrance family<select id="familyFilter"><option>All</option>${['Amber','Floral','Fresh','Fruity','Gourmand','Woody'].map(f=>`<option ${family===f?'selected':''}>${f}</option>`).join('')}</select></label><label>Maximum 50 ml price <b id="priceLabel">${money(6000)}</b><input id="priceFilter" type="range" min="3000" max="6000" step="100" value="6000"></label><label>Collection<select id="editFilter"><option value="all" ${edit==='all'?'selected':''}>All fragrances</option><option value="signature" ${edit==='signature'?'selected':''}>Signature edit</option><option value="new" ${edit==='new'?'selected':''}>New arrivals</option></select></label><button class="text-link" data-action="reset-filters">Reset filters</button><a class="filter-help" href="#/quiz">Not sure? <b>Find your scent ↗</b></a></aside><div><p id="resultCount" class="result-count" aria-live="polite"></p><div class="product-grid" id="shopProducts"></div></div></div></section>`}
let shopGender='All';
function renderShop(){const list=filterProducts({gender:shopGender,query:$('#shopSearch').value,family:$('#familyFilter').value,maxPrice:$('#priceFilter').value,sort:$('#shopSort').value,edit:$('#editFilter').value});$('#resultCount').textContent=`${list.length} fragrance${list.length===1?'':'s'} · indicative 50 ml pricing`;$('#priceLabel').textContent=money(Number($('#priceFilter').value));$('#shopProducts').innerHTML=list.length?cards(list):`<div class="empty-state"><h2>No scent found just yet.</h2><p>Try a different note or open up your filters.</p><button class="button" data-action="reset-filters">RESET FILTERS</button></div>`}
function productView(p){productSize=50;productQty=1;recent=[p.id,...recent.filter(id=>id!==p.id)].slice(0,6);write('maison-recent',recent);return `<div class="breadcrumbs"><a href="#/">Home</a> / <a href="#/shop">Collection</a> / ${p.name}</div><section class="product-page"><div class="product-gallery"><div class="gallery-main tone-${p.family.toLowerCase()}" id="galleryMain">${bottle(p,'large-bottle')}<span>${p.family.toUpperCase()} / ${p.mood.toUpperCase()}</span></div><div class="gallery-thumbs"><button class="active" data-gallery="bottle" data-id="${p.id}" aria-label="View fragrance bottle" aria-pressed="true">${bottle(p)}</button><button data-gallery="notes" data-id="${p.id}" aria-label="View fragrance notes" aria-pressed="false"><span>TOP<br>HEART<br>BASE</span></button><button data-gallery="campaign" data-id="${p.id}" aria-label="View MAISON campaign image" aria-pressed="false"><img src="assets/maison-campaign.png" alt="MAISON campaign" loading="lazy"></button></div></div><div class="product-info"><p class="eyebrow">${p.tag.toUpperCase()} · ${p.category.toUpperCase()}</p><h1>${p.name}</h1><p class="product-subtitle">${p.family}. ${p.mood}. A little more you.</p><p class="product-description">${p.description}</p><div class="product-price" id="productPrice">${money(p.price)} <small>indicative price</small></div><fieldset class="variant-picker"><legend>Choose your size <span>EAU DE PARFUM</span></legend>${p.variants.map(v=>`<button data-size="${v.size}" data-id="${p.id}" class="${v.size===50?'active':''}" aria-pressed="${v.size===50}">${v.size} ml<span>${money(v.price)}</span></button>`).join('')}</fieldset><div class="purchase-row"><div class="quantity-selector"><button data-product-qty="-1" aria-label="Decrease quantity">−</button><span id="productQty">1</span><button data-product-qty="1" aria-label="Increase quantity">+</button></div><button class="button" data-product-add="${p.id}">ADD TO BAG <span>+</span></button></div><div class="product-links"><button data-save="${p.id}">${saved.includes(p.id)?'♥ Saved to favorites':'♡ Save for later'}</button><button data-compare="${p.id}">⇄ Compare fragrance</button><button data-share="${p.id}">Share ↗</button></div><a class="bundle-nudge" href="#/bundle?first=${p.id}"><span>WHY STOP AT ONE?</span><b>Build your personal fragrance wardrobe ↗</b></a><p class="fine-print">Proposed scent profile and sizes. Final ingredients, concentration, and availability will be confirmed at launch.</p><div class="product-accordions"><details open><summary>The notes <span>+</span></summary>${notePyramid(p)}</details><details><summary>When to wear it <span>+</span></summary><p>${p.occasion.join(' · ')}<br>${p.season}. These are suggestions; choose what feels right to you.</p></details><details><summary>Ingredients & concentration <span>+</span></summary><p>The final ingredient list, allergens, and oil concentration will be published after formulation is confirmed. Note descriptions are not ingredient lists.</p></details><details><summary>Shipping & returns <span>+</span></summary><p>Online ordering is not open yet. Shipping regions, delivery rates, and return terms will be published before launch.</p></details></div></div></section>${detailSections(p,{bottle,money})}<section class="section">${heading('YOUR NEXT DISCOVERY','A different side of your signature.')}<div class="product-rail">${cards(products.filter(other=>other.id!==p.id).sort((a,b)=>Number(b.family===p.family)-Number(a.family===p.family)).slice(0,4))}</div></section>${reviewsBlock()}`}
function notePyramid(p){return `<div class="notes-pyramid">${[['THE OPENING',p.top],['THE HEART',p.heart],['THE FINISH',p.base]].map(([label,notes],i)=>`<div><span>0${i+1}</span><div><b>${label}</b><p>${notes.join(' · ')}</p></div></div>`).join('')}</div>`}
function bundleView(params){const selected=params.get('set'),first=Number(params.get('first'));if(selected!==null&&curated[Number(selected)]){bundleIds=[...curated[Number(selected)].ids];bundleCount=3}else if(first&&byId(first)&&!bundleIds.includes(first)){bundleIds=[first];bundleCount=3}return `<section class="page-top"><p class="eyebrow">YOUR PERSONAL FRAGRANCE WARDROBE</p><h1>Good things come together.</h1><p>Choose a ready-made edit or build a collection of your own.</p></section><section class="section bundle-page"><div class="bundle-builder"><div><div class="builder-heading"><h2>Build your own set.</h2><p>Different days. Different moods. Always you.</p></div><div class="builder-options"><fieldset><legend>01 / YOUR SET</legend>${settings.bundleTiers.map(t=>`<button class="pill ${bundleCount===t.count?'active':''}" data-bundle-count="${t.count}">${t.count} fragrances</button>`).join('')}</fieldset><label>02 / BOTTLE SIZE<select id="bundleSize">${[30,50,100].map(size=>`<option value="${size}" ${bundleSize===size?'selected':''}>${size} ml</option>`).join('')}</select></label></div><div class="tab-list">${['All','Women','Men','Unisex'].map(g=>`<button class="pill ${g===bundleGender?'active':''}" data-bundle-gender="${g}">${g==='All'?'All fragrances':g}</button>`).join('')}</div><div id="bundleProducts" class="product-grid bundle-product-grid"></div></div><aside class="bundle-summary" id="bundleSummary"></aside></div></section><section class="section">${heading('LEAVE IT TO US','The ready-made edits.')}<div class="curated-grid">${curatedCards()}</div></section>`}
function renderBundle(){if(!$('#bundleProducts'))return;$('#bundleProducts').innerHTML=cards(products.filter(p=>bundleGender==='All'||p.category===bundleGender),{bundle:true});$('#bundleSummary').innerHTML=`<p class="eyebrow">${bundleCount===3?'THE SIGNATURE TRIO':'THE FULL WARDROBE'}</p><h2>Your set, your way.</h2><div class="builder-progress" role="progressbar" aria-label="Bundle selection progress" aria-valuemin="0" aria-valuemax="${bundleCount}" aria-valuenow="${bundleIds.length}"><span style="width:${bundleIds.length/bundleCount*100}%"></span></div><p class="bundle-status" role="status">${bundleIds.length} of ${bundleCount} selected · ${bundleSize} ml bottles</p><div class="bundle-slots">${Array.from({length:bundleCount},(_,i)=>{const p=byId(bundleIds[i]);return p?`<div class="bundle-slot filled">${bottle(p)}<div><b>${p.name}</b><span>${money(p.variants.find(v=>v.size===bundleSize).price)}</span></div><button data-bundle-item="${p.id}" aria-label="Remove ${p.name} from bundle">×</button></div>`:`<div class="bundle-slot"><span class="slot-number">0${i+1}</span><span>Your next favorite</span></div>`}).join('')}</div><div class="bundle-total"><span>Your set total</span><b>${money(bundleTotal(bundleIds,bundleSize))}</b></div><p class="fine-print">Indicative pricing. No launch discounts, shipping offers, or gifts have been confirmed.</p><button class="button full" data-action="add-bundle" ${bundleIds.length!==bundleCount?'disabled':''}>${bundleIds.length===bundleCount?'ADD MY SET TO BAG':'CHOOSE '+(bundleCount-bundleIds.length)+' MORE'} <span>+</span></button><button class="text-link" data-action="reset-bundle">Start again</button>`}
function quizView(){if(quizStep>=quizQuestions.length){const results=recommend(quizAnswers);return `<section class="quiz-results section"><p class="eyebrow">YOUR SCENT PERSONALITY / ${esc(quizAnswers.mood||'CURIOUS').toUpperCase()}</p><h1>Your kind of signature.</h1><p>A few possibilities, chosen around the notes and moments you love.</p><div class="quiz-answer-summary">${Object.values(quizAnswers).map(v=>`<span class="pill">${esc(v)}</span>`).join('')}</div><div class="product-grid">${cards(results)}</div><div class="quiz-result-actions"><button class="button" data-action="quiz-bundle">BUILD A SET WITH MY MATCHES ↗</button><button class="text-link" data-action="quiz-reset">Take it again</button></div><p class="fine-print">Recommendations are based on your answers and the preview scent profiles.</p></section>`}const q=quizQuestions[quizStep];return `<section class="quiz-page"><div class="quiz-aside"><p class="eyebrow">THE MAISON SCENT FINDER</p><h2>A little intuition.<br>A little inspiration.<br>A little more you.</h2><div class="quiz-art">${bottle(byId([1,3,2,4][quizStep]))}</div><p>01 / FOLLOW YOUR SENSES</p></div><div class="quiz-content"><div class="quiz-progress">${quizQuestions.map((_,i)=>`<span class="${i<=quizStep?'done':''}"></span>`).join('')}</div><p class="eyebrow">QUESTION ${quizStep+1} OF ${quizQuestions.length}</p><h1>${q.title}</h1><p>${q.intro}</p><div class="quiz-choices">${q.options.map(([value,title,description])=>`<button data-quiz-answer="${value}" class="${quizAnswers[q.key]===value?'selected':''}"><div><b>${title}</b><span>${description}</span></div><span>↗</span></button>`).join('')}</div>${quizStep?'<button class="text-link" data-action="quiz-back">← Previous question</button>':'<a class="text-link" href="#/shop">Browse the collection instead ↗</a>'}</div></section>`}
function guideView(){return `<section class="page-top"><p class="eyebrow">THE MAISON FRAGRANCE GUIDE</p><h1>A little knowledge.<br>A better sense of you.</h1><p>Explore families, notes, and concentration types without the complicated vocabulary.</p></section><section class="section family-guide">${heading('START WITH WHAT YOU LOVE','Find your fragrance family.')}<div class="family-guide-grid">${[['Fresh','Citrus, tea, green leaves. A bright and airy place to begin.',4],['Floral','Petals, white flowers, and a softer kind of expression.',3],['Woody','Dry cedar, creamy sandalwood, and earthy depth.',2],['Amber','Warm, enveloping profiles with amber and spice.',1],['Gourmand','Vanilla, almond, and sweet, comforting impressions.',5],['Fruity','Juicy, playful profiles with peach and soft fruit.',8]].map(([family,description,id])=>`<a href="#/shop?family=${family}" class="family-guide-card tone-${family.toLowerCase()}">${bottle(byId(id))}<div><h3>${family}</h3><p>${description}</p><span class="text-link">Explore ${family.toLowerCase()} ↗</span></div></a>`).join('')}</div></section><section class="section concentration-section"><div><p class="eyebrow">THE CONCENTRATION QUESTION</p><h2>More than a percentage.</h2><p>Different fragrance labels describe different styles and concentration levels. Select a type to explore what it generally means.</p><p>Names and concentrations vary by maker. A higher percentage alone does not guarantee a particular wear time, quality, or projection.</p><p class="fine-print">MAISON formulations and oil percentages have not been finalized. This is an educational comparison, not a product specification.</p></div><div class="concentration-tool"><div class="tab-list">${[['mist','Mist'],['edt','Eau de toilette'],['edp','Eau de parfum'],['extrait','Extrait']].map(([v,t],i)=>`<button data-concentration="${v}" class="pill ${i===2?'active':''}" aria-pressed="${i===2}">${t}</button>`).join('')}</div><div id="concentrationInfo"></div></div></section><section class="section note-guide">${heading('THE LIFE OF A SCENT','Opening. Heart. Finish.')}<div class="note-guide-grid">${[['01','Top notes','The opening impression. Often bright or aromatic, inviting you into the composition.'],['02','Heart notes','The central character. Florals, spices and other accords give the fragrance its personality.'],['03','Base notes','The foundation. Woods, musks and warm accords bring texture and depth.']].map(([n,t,d])=>`<article><span>${n}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section><section class="quiz-banner"><p class="eyebrow">PUT YOUR CURIOSITY TO WORK</p><h2>Let's find your notes.</h2><a class="button" href="#/quiz">TAKE THE SCENT QUIZ ↗</a></section>`}
const concentrationInfo={mist:['Fragrance mist','Usually a light, easygoing style designed for a gentle fragrance impression.','LIGHT'],edt:['Eau de toilette','Often a fresher, lighter interpretation. The formula and ingredients matter as much as the name.','LIGHTER'],edp:['Eau de parfum','Often a more concentrated interpretation, with space for a fuller composition and texture.','FULLER'],extrait:['Extrait / parfum','Often a concentrated style focused on depth and richness. Exact percentages are specific to the formula.','CONCENTRATED']};
function renderConcentration(type='edp'){const data=concentrationInfo[type];$('#concentrationInfo').innerHTML=`<div class="concentration-art"><span class="concentration-level level-${type}"></span><span>${data[2]}</span></div><h3>${data[0]}</h3><p>${data[1]}</p><small>How it wears depends on the formula, application, environment, and your skin.</small>`}
function savedView(){const list=saved.map(byId);return `<section class="page-top"><p class="eyebrow">YOUR PERSONAL SHORTLIST</p><h1>A few favorites.</h1><p>Saved in this browser, ready when you are.</p></section><section class="section"><div class="product-grid" id="savedProducts">${list.length?cards(list):empty('Your signature is still out there.','Tap the heart on a fragrance to keep it here.','#/shop','EXPLORE THE COLLECTION')}</div></section>${recent.length?`<section class="section">${heading('TAKE ANOTHER LOOK','Recently discovered.')}<div class="product-rail">${cards(recent.map(byId).filter(Boolean))}</div></section>`:''}`}
function empty(title,text,href,label){return `<div class="empty-state"><span class="empty-icon">✳</span><h2>${title}</h2><p>${text}</p>${href?`<a href="${href}" class="button">${label} ↗</a>`:''}</div>`}
function pageTitle(kicker,title,description=''){return `<section class="page-top"><p class="eyebrow">${kicker}</p><h1>${title}</h1>${description?`<p>${description}</p>`:''}</section>`}
function infoView(route){if(route==='story')return `${pageTitle('THE WORLD OF MAISON','The little things<br>that feel like you.','Our vision for a more personal, everyday fragrance ritual.')}<section class="story-editorial section"><img src="assets/maison-campaign.png" alt="MAISON fragrance campaign on warm stone" width="1536" height="1024"><div><p class="eyebrow">A SCENT OF YOUR OWN</p><h2>Room for a little luxury.<br>Every single day.</h2><p>We started MAISON around a simple idea: fragrance should feel personal. It should fit your mood, your moments, and the way you move through your day.</p><p>Our proposed collection explores the contrast between bright citrus and warm amber, quiet woods and expressive florals. A scent for the everyday, and room for a second favorite.</p><p>We are preparing the collection for launch. Final formulation, sourcing, manufacturing details, and product specifications will be published when confirmed.</p><a class="button" href="#/shop">EXPLORE THE COLLECTION ↗</a></div></section>${newsletter()}`;
if(route==='support')return `${pageTitle('HERE TO HELP','A little clarity.','Answers to the questions you might have about MAISON.')}<section class="section support-layout"><div class="support-index"><a href="#/shipping">Shipping & returns ↗</a><a href="#/track">Track an order ↗</a><a href="#/privacy">Your privacy ↗</a><a href="#/partners">Wholesale & partnerships ↗</a><div class="support-card"><h3>Contact information</h3><p>Our support contact will be published before orders open. No messages or personal details are collected on this preview site.</p></div></div>${faqs()}</section>`;
if(route==='reviews')return `${pageTitle('THE MAISON COMMUNITY','Good scents.<br>Honest experiences.','A place for customer stories, when the collection launches.')}${reviewsBlock()}<section class="prose"><h2>How reviews will work</h2><p>Published reviews will reflect real customer experiences. There are currently no MAISON customer ratings, testimonials, or verified purchases. We do not carry over ratings from the websites that inspired our design.</p><a class="text-link" href="#/shop">Get to know the collection ↗</a></section>`;
if(route==='journal')return `${pageTitle('THE SCENT JOURNAL','A little inspiration, bottled.','Notes, rituals, and a fresh perspective on fragrance.')}<section class="section journal-grid">${journalCards()}</section>`;
const content={shipping:['Shipping & returns','We are preparing for our first orders.','Online ordering is not open yet. Shipping destinations, rates, delivery estimates, return eligibility, and refund procedures will be published before you can place an order. No free shipping or money-back guarantee is active during this preview.'],track:['Track your order','Your next chapter is coming.','MAISON is not accepting orders yet, so there are no MAISON shipments to track. Order tracking and purchase history will become available after checkout and fulfillment are connected.'],locations:['Find us','Everywhere starts somewhere.','MAISON has no confirmed retail locations at this time. Store addresses and opening hours will be published here if in-person shopping becomes available.'],partners:['Wholesale & partnerships','Make something good together.','Wholesale, private label, creator partnerships, and affiliate opportunities are being considered. There is no active application program or wholesale ordering portal yet. Business contact details will be published before applications open.'],rewards:['Rewards & referrals','A little more to look forward to.','Rewards, referral credits, and promotional gifts are not active yet. The earning rules, redemption limits, and complete terms will be published before any program begins. No points or entries are earned by browsing this preview.'],privacy:['Your privacy','Your choices stay with you.','Your bag, saved fragrances, recently viewed items, scent quiz answers, and optional bag note can be stored in this browser. They are not submitted to a store server. No email subscriptions, accounts, or payments are collected. The site is hosted on GitHub Pages and loads fonts from Google Fonts. The attributed inspiration library also loads product photos and scent diagrams from the source retailers and their Shopify image CDN. Your browser connects to those services when loading the site. Use “Manage saved data” to clear MAISON browser storage. A complete privacy notice will be published before accounts or checkout launch.'],terms:['Store information','A collection in preparation.','The MAISON catalog is a proposed collection for our store launch. Fragrance profiles, bottle sizes, and prices are indicative. Adding products to a bag does not reserve stock or create an order. No payments are collected and no purchase contract is formed. The original campaign image is an AI-generated product concept. Confirmed product photography, ingredient disclosures, sales terms, and policies will be published before orders open.']};const c=content[route];return c?`${pageTitle('MAISON / INFORMATION',c[0],c[1])}<section class="prose"><p>${c[2]}</p><a class="button" href="#/shop">EXPLORE THE COLLECTION ↗</a></section>`:pageTitle('404 / A DIFFERENT DIRECTION','This page is still out there.','Use the navigation to find your way back to the collection.')}
function renderRoute(){detailsCleanup();detailsCleanup=()=>{};closeAll();document.body.classList.remove('menu-open');$('#menuToggle').setAttribute('aria-expanded','false');$('.nav-toggle').setAttribute('aria-expanded','false');$('.nav-dropdown').classList.remove('open');const [path,query='']=(location.hash.slice(1)||'/').split('?'),parts=path.split('/').filter(Boolean),page=parts[0]||'home',params=new URLSearchParams(query);let html,title;if(page==='home'){html=home();title='Make it your signature.'}else if(page==='shop'){shopGender=params.get('gender')||'All';html=shop(params);title='Shop the collection'}else if(page==='references'){html=referenceShell();title='The inspiration library'}else if(page==='reference-stores'){html=referenceStoreGuide();title='About the reference stores'}else if(page==='product'){const p=products.find(p=>p.slug===parts[1]);html=p?productView(p):infoView('404');title=p?.name||'Fragrance not found'}else if(page==='bundle'){html=bundleView(params);title='Build your bundle'}else if(page==='quiz'){html=quizView();title='Find your scent'}else if(page==='guide'){html=guideView();title='The fragrance guide'}else if(page==='saved'){html=savedView();title='Your favorites'}else if(page==='journal'&&parts[1]){const a=articles.find(a=>a.slug===parts[1]);html=a?`${pageTitle(a.category+' · '+a.minutes+' MIN READ',a.title,a.intro)}<article class="prose journal-prose">${a.sections.map(([title,text])=>`<h2>${title}</h2><p>${text}</p>`).join('')}<a class="text-link" href="#/journal">← Back to the journal</a></article>`:infoView('404');title=a?.title||'Story not found'}else{html=infoView(page);title=page.charAt(0).toUpperCase()+page.slice(1)}$('#main').innerHTML=html;if(page==='product'){const current=products.find(p=>p.slug===parts[1]);if(current)detailsCleanup=enhanceProductDetails(current,money,ids=>{compared=[];document.querySelectorAll('[data-compare]').forEach(el=>{el.classList.remove('selected');el.setAttribute('aria-pressed','false')});ids.forEach(toggleCompare);showCompare()})}if(page==='references')void mountReferences(parts,params);document.title=`${title} | MAISON`;if(page==='shop')renderShop();if(page==='bundle')renderBundle();if(page==='guide')renderConcentration();updateCounts();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true})}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2700)}
function updateCounts(){const count=summarize(cart).count;$('#bagCount').textContent=count;$('#bagTitleCount').textContent=`(${count})`;$('#wishCount').textContent=saved.length;$('#compareDock').hidden=compared.length===0;$('#compareDock').innerHTML=`<span><b>${compared.length} / 3</b> fragrances to compare</span><button data-action="compare" ${compared.length<2?'disabled':''}>COMPARE ↗</button><button data-action="clear-compare" aria-label="Clear comparison">×</button>`}
function saveCart(){write('maison-bag-v2',cart);updateCounts();if($('#bag').open)renderBag()}
function add(id,size=50,qty=1){cart=addItem(cart,id,size,qty);saveCart();toast('Added to your bag. A little more you.')}
function renderBag(){const summary=summarize(cart),target=summary.count<3?3:summary.count<5?5:5,progress=Math.min(100,summary.count/target*100);$('#bagBody').innerHTML=!cart.length?empty('Your signature is waiting.','Explore the collection to start your everyday ritual.','#/shop','FIND MY FRAGRANCE'):`<div class="bag-progress"><p>${summary.count<3?`A set starts with three. Add ${3-summary.count} more to explore your fragrance wardrobe.`:summary.count<5?'Your signature trio is taking shape. Explore five for a fuller wardrobe.':'A fragrance for every side of you.'}</p><div class="builder-progress"><span style="width:${progress}%"></span></div><small>3 / THE SIGNATURE TRIO <span>5 / THE FULL WARDROBE</span></small></div><div class="bag-items">${cart.map(row=>{const p=byId(row.id),variant=p.variants.find(v=>v.size===row.size);return `<article class="bag-row"><a href="#/product/${p.slug}" class="bag-art tone-${p.family.toLowerCase()}" aria-label="View ${p.name}">${bottle(p)}</a><div><a href="#/product/${p.slug}">${p.name}</a><p>${row.size} ml · ${p.family}</p><div class="quantity-selector"><button data-cart-qty="-1" data-id="${p.id}" data-size="${row.size}" aria-label="Decrease ${p.name} quantity">−</button><span>${row.qty}</span><button data-cart-qty="1" data-id="${p.id}" data-size="${row.size}" aria-label="Increase ${p.name} quantity">+</button></div><button class="remove-link" data-remove="${p.id}" data-size="${row.size}">Remove</button></div><b>${money(variant.price*row.qty)}</b></article>`}).join('')}</div><details class="order-note" ${note?'open':''}><summary>Add a note to your bag <span>+</span></summary><label for="orderNote">Optional note, saved only in this browser.</label><textarea id="orderNote" maxlength="500" placeholder="A reminder for your collection…">${esc(note)}</textarea><small id="noteStatus" role="status">${note?'Note saved on this device.':'No note added.'}</small></details><div class="bag-recommendation"><span class="eyebrow">A LITTLE MORE POSSIBILITY</span>${(()=>{const p=products.find(p=>!cart.some(row=>row.id===p.id));return p?`<div>${bottle(p)}<div><b>${p.name}</b><p>${p.family} · ${money(p.price)}</p></div><button class="text-link" data-add="${p.id}">Add +</button></div>`:'<p>Your collection spans every preview fragrance.</p>'})()}</div><div class="bag-summary"><div><span>Subtotal</span><b>${money(summary.subtotal)}</b></div><p>Indicative pricing. Shipping, discounts, and gifts are not active.</p><button class="button full" data-action="checkout">CHECKOUT AVAILABILITY ↗</button><button class="text-link" data-close="bag">Continue exploring</button></div>`}
function openDialog(id){const d=$('#'+id);if(!d.open)d.showModal();document.body.classList.add('dialog-open')}
function closeDialog(id){$('#'+id)?.close();if(!document.querySelector('dialog[open]'))document.body.classList.remove('dialog-open')}
function closeAll(){document.querySelectorAll('dialog[open]').forEach(d=>d.close());document.body.classList.remove('dialog-open')}
function modal(title,html,cls=''){closeAll();$('#modalTitle')?.remove();$('#modalBody').innerHTML=`<h2 id="modalTitle">${title}</h2>${html}`;$('#modal').className=cls;openDialog('modal')}
function showQuick(id){const p=byId(id);modal(p.name,`<div class="quick-product"><div class="quick-art tone-${p.family.toLowerCase()}">${bottle(p)}</div><div><p class="eyebrow">${p.category} / ${p.family}</p><p>${p.description}</p><label>Choose your size<select id="quickSize">${p.variants.map(v=>`<option value="${v.size}" ${v.size===50?'selected':''}>${v.size} ml · ${money(v.price)}</option>`).join('')}</select></label><button class="button full" data-quick-add="${p.id}">ADD TO BAG +</button><a class="text-link" href="#/product/${p.slug}">Explore the fragrance ↗</a></div></div>`,'quick-modal')}
function renderSearch(){const query=$('#searchInput').value.trim(),list=filterProducts({query}).slice(0,6);$('#searchResults').innerHTML=`<p class="eyebrow">${query?`${list.length} MATCHES`:'A LITTLE INSPIRATION'}</p>${list.length?`<div class="search-result-grid">${list.map(p=>`<a class="search-result" href="#/product/${p.slug}"><div class="tone-${p.family.toLowerCase()}">${bottle(p)}</div><div><b>${p.name}</b><span>${p.family} · ${money(p.price)}</span></div><span>↗</span></a>`).join('')}</div><a class="button full secondary" href="#/shop?q=${encodeURIComponent(query)}">VIEW ALL RESULTS ↗</a>`:'<p>No fragrances found. Try a note such as rose, cedar, or vanilla.</p>'}`}
function toggleSave(id){id=Number(id);if(!byId(id))return;saved=saved.includes(id)?saved.filter(v=>v!==id):[...saved,id];write('maison-favorites',saved);document.querySelectorAll(`[data-save="${id}"]`).forEach(b=>{const selected=saved.includes(id);b.setAttribute('aria-pressed',selected);if(b.classList.contains('heart')){b.classList.toggle('selected',selected);b.textContent=selected?'♥':'♡';b.setAttribute('aria-label',`${selected?'Unsave':'Save'} ${byId(id).name}`)}else b.textContent=selected?'♥ Saved to favorites':'♡ Save for later'});if(location.hash==='#/saved')$('#savedProducts').innerHTML=saved.length?cards(saved.map(byId)):empty('Your signature is still out there.','Tap a heart to save a fragrance.','#/shop','EXPLORE');updateCounts();toast(saved.includes(id)?'Saved for another day.':'Removed from your favorites.')}
function toggleCompare(id){id=Number(id);if(!byId(id))return;if(compared.includes(id))compared=compared.filter(v=>v!==id);else if(compared.length<3)compared.push(id);else return toast('Compare up to three fragrances. Remove one to choose another.');document.querySelectorAll(`[data-compare="${id}"]`).forEach(b=>{b.classList.toggle('selected',compared.includes(id));b.setAttribute('aria-pressed',compared.includes(id))});updateCounts()}
function showCompare(){if(compared.length<2)return;modal('Find your kind of fragrance.',`<div class="compare-scroll"><table class="compare-table"><thead><tr><th scope="col">The details</th>${compared.map(id=>`<th scope="col">${bottle(byId(id))}<a href="#/product/${byId(id).slug}">${byId(id).name}</a></th>`).join('')}</tr></thead><tbody>${[['50 ml price',p=>money(p.price)],['Family',p=>p.family],['Opening',p=>p.top.join(', ')],['Heart',p=>p.heart.join(', ')],['Finish',p=>p.base.join(', ')],['Mood',p=>p.mood],['Occasions',p=>p.occasion.join(', ')],['Season suggestion',p=>p.season]].map(([label,value])=>`<tr><th scope="row">${label}</th>${compared.map(id=>`<td>${value(byId(id))}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">Make it yours</th>${compared.map(id=>`<td><button class="button secondary" data-add="${id}">ADD TO BAG +</button></td>`).join('')}</tr></tbody></table></div><p class="fine-print">Comparison of the proposed MAISON profiles. Formulations are not yet finalized.</p>`,'compare-modal')}
function viewQuiz(){const y=window.scrollY;$('#main').innerHTML=quizView();window.scrollTo({top:quizStep>=quizQuestions.length?0:y,behavior:'instant'});$('#main').focus({preventScroll:true})}
document.addEventListener('click',async event=>{const b=event.target.closest('button,a');if(!b)return;const d=b.dataset;if(d.close){closeDialog(d.close);return}if(d.save){toggleSave(d.save);return}if(d.compare){toggleCompare(d.compare);return}if(d.add){add(Number(d.add));return}if(d.quick){showQuick(Number(d.quick));return}if(d.quickAdd){add(Number(d.quickAdd),Number($('#quickSize').value));return}if(d.productAdd){add(Number(d.productAdd),productSize,productQty);return}if(d.cartQty){const row=cart.find(row=>row.id===Number(d.id)&&row.size===Number(d.size));if(!row)return;row.qty=Math.min(99,row.qty+Number(d.cartQty));cart=cart.filter(row=>row.qty>0);saveCart();return}if(d.remove){cart=cart.filter(row=>!(row.id===Number(d.remove)&&row.size===Number(d.size)));saveCart();return}if(d.size&&b.closest('.variant-picker')){productSize=Number(d.size);const p=byId(d.id);document.querySelectorAll('.variant-picker button').forEach(el=>{el.classList.toggle('active',Number(el.dataset.size)===productSize);el.setAttribute('aria-pressed',Number(el.dataset.size)===productSize)});$('#productPrice').innerHTML=`${money(p.variants.find(v=>v.size===productSize).price)} <small>indicative price</small>`;return}if(d.productQty){productQty=Math.max(1,Math.min(99,productQty+Number(d.productQty)));$('#productQty').textContent=productQty;return}if(d.gallery){const p=byId(d.id);$('#galleryMain').innerHTML=d.gallery==='notes'?notePyramid(p):d.gallery==='campaign'?'<img class="campaign-gallery" src="assets/maison-campaign.png" alt="Original MAISON campaign product concept">':bottle(p,'large-bottle');document.querySelectorAll('[data-gallery]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',el===b)});return}if(d.share){const url=location.href;try{await navigator.clipboard.writeText(url);toast('Fragrance link copied.')}catch{modal('Share this fragrance.',`<label>Copy this link<input readonly value="${esc(url)}"></label>`)}return}if(d.homeGender){document.querySelectorAll('[data-home-gender]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',el===b)});$('#signatureRail').innerHTML=cards(products.filter(p=>d.homeGender==='All'||p.category===d.homeGender));return}if(d.shopGender){shopGender=d.shopGender;document.querySelectorAll('[data-shop-gender]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',el===b)});renderShop();return}if(d.rail){const rail=$('#'+d.rail);rail.scrollBy({left:rail.clientWidth*Number(d.direction)*.8,behavior:'smooth'});return}if(d.reviewTopic){document.querySelectorAll('[data-review-topic]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',el===b)});$('#reviewResults').innerHTML=`<span class="empty-icon">“</span><h3>${d.reviewTopic==='All'?'A new story starts here.':esc(d.reviewTopic)+' stories are on their way.'}</h3><p>No customer reviews have been collected yet. Reviews will appear after launch.</p>`;return}if(d.curated!==undefined){const set=curated[Number(d.curated)];if(!set)return;bundleIds=[...set.ids];bundleCount=3;bundleSize=50;bundleGender='All';if(location.hash.startsWith('#/bundle')){renderBundle();window.scrollTo({top:0,behavior:'smooth'})}else location.hash='/bundle';return}if(d.bundleCount){bundleCount=Number(d.bundleCount);bundleIds=bundleIds.slice(0,bundleCount);renderBundle();return}if(d.bundleGender){bundleGender=d.bundleGender;document.querySelectorAll('[data-bundle-gender]').forEach(el=>el.classList.toggle('active',el===b));renderBundle();return}if(d.bundleItem){const id=Number(d.bundleItem);if(bundleIds.includes(id))bundleIds=bundleIds.filter(v=>v!==id);else if(bundleIds.length<bundleCount)bundleIds.push(id);else return toast('Your set is full. Remove a fragrance to choose a different one.');renderBundle();return}if(d.quizAnswer){quizAnswers[quizQuestions[quizStep].key]=d.quizAnswer;write('maison-quiz',quizAnswers);quizStep++;viewQuiz();return}if(d.concentration){document.querySelectorAll('[data-concentration]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',el===b)});renderConcentration(d.concentration);return}
switch(d.action){case 'search':closeAll();renderSearch();openDialog('searchDialog');$('#searchInput').focus();break;case 'cart':closeAll();renderBag();openDialog('bag');break;case 'account':modal('Your MAISON account.',`<p>Accounts, secure sign-in, and order history will open alongside online ordering. You can save fragrances and a bag in this browser without an account.</p><a class="button full" href="#/saved">MY FAVORITES ↗</a>`);break;case 'reset-filters':shopGender='All';$('#shopSearch').value='';$('#familyFilter').value='All';$('#priceFilter').value=6000;$('#editFilter').value='all';$('#shopSort').value='featured';document.querySelectorAll('[data-shop-gender]').forEach(el=>{el.classList.toggle('active',el.dataset.shopGender==='All');el.setAttribute('aria-pressed',el.dataset.shopGender==='All')});renderShop();break;case 'compare':showCompare();break;case 'clear-compare':compared=[];document.querySelectorAll('[data-compare]').forEach(el=>{el.classList.remove('selected');el.setAttribute('aria-pressed','false')});updateCounts();break;case 'add-bundle':if(bundleIds.length===bundleCount){bundleIds.forEach(id=>cart=addItem(cart,id,bundleSize));saveCart();renderBag();openDialog('bag');toast('Your fragrance wardrobe is in your bag.')}break;case 'reset-bundle':bundleIds=[];renderBundle();break;case 'quiz-back':quizStep=Math.max(0,quizStep-1);viewQuiz();break;case 'quiz-reset':quizStep=0;quizAnswers={};viewQuiz();break;case 'quiz-bundle':bundleIds=recommend(quizAnswers).map(p=>p.id);bundleCount=3;bundleSize=50;location.hash='/bundle';break;case 'checkout':modal('Your next chapter is coming.',`<p>Your bag is saved in this browser. MAISON is not accepting payments or orders yet.</p><div class="checkout-summary"><span>${summarize(cart).count} fragrance${summarize(cart).count===1?'':'s'}</span><b>${money(summarize(cart).subtotal)}</b></div><p>Confirmed product information, shipping and returns, and secure payment will be available when ordering opens.</p><button class="button full" data-action="cart">BACK TO MY BAG ↗</button>`);break;case 'clear-local':modal('Your choices, your device.',`<p>You can clear your saved bag, notes, favorites, quiz answers, and recently viewed fragrances from this browser.</p><button class="button full" data-action="confirm-clear">CLEAR MY SAVED DATA</button>`);break;case 'confirm-clear':for(const key of ['maison-cart','maison-bag-v2','maison-order-note','maison-favorites','maison-recent','maison-quiz'])try{localStorage.removeItem(key)}catch{}cart=[];saved=[];recent=[];note='';quizAnswers={};quizStep=0;bundleIds=[];compared=[];closeAll();renderRoute();toast('Your saved MAISON data has been cleared.');break;}
if(b.tagName==='A'&&b.getAttribute('href')?.startsWith('#/'))closeAll();if(b.closest('#navigation')&&b.tagName==='A'){document.body.classList.remove('menu-open');$('#menuToggle').setAttribute('aria-expanded','false')}
});
document.addEventListener('input',e=>{if(['shopSearch','priceFilter'].includes(e.target.id))renderShop();if(e.target.id==='searchInput')renderSearch();if(e.target.id==='orderNote'){note=e.target.value.slice(0,500);write('maison-order-note',note);$('#noteStatus').textContent=note?'Note saved on this device.':'No note added.'}});
document.addEventListener('change',e=>{if(['shopSort','familyFilter','editFilter'].includes(e.target.id))renderShop();if(e.target.id==='bundleSize'){bundleSize=Number(e.target.value);renderBundle()}});
$('#menuToggle').onclick=()=>{const open=document.body.classList.toggle('menu-open');$('#menuToggle').setAttribute('aria-expanded',open)};
$('.nav-toggle').onclick=()=>{const open=$('.nav-dropdown').classList.toggle('open');$('.nav-toggle').setAttribute('aria-expanded',open)};
document.addEventListener('click',e=>{if(!e.target.closest('.nav-dropdown')){$('.nav-dropdown').classList.remove('open');$('.nav-toggle').setAttribute('aria-expanded','false')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('menu-open');$('#menuToggle').setAttribute('aria-expanded','false');$('.nav-dropdown').classList.remove('open');$('.nav-toggle').setAttribute('aria-expanded','false')}});
document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d.id)}});d.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.body.classList.remove('dialog-open')})});
window.addEventListener('hashchange',renderRoute);$('#year').textContent=new Date().getFullYear();renderRoute();
